import { formatWithSeparators, getRegexpIndices } from ".";

describe("string utils", () => {
  it("getRegexpIndices", () => {
    const regexp = new RegExp(":", "g");
    expect(getRegexpIndices("", regexp)).toEqual([]);
    expect(getRegexpIndices(":", regexp)).toEqual([0]);
    expect(getRegexpIndices("12:12", regexp)).toEqual([2]);
    expect(getRegexpIndices("12:12:12", regexp)).toEqual([2, 5]);
    expect(getRegexpIndices("123:123:123", regexp)).toEqual([3, 7]);
    expect(getRegexpIndices("1:2:3:4:5", regexp)).toEqual([1, 3, 5, 7]);
  });

  it("formatWithSeparators", () => {
    const format = (value: string, format: string, separator: string) => {
      const regexp = new RegExp(separator, "g");
      const indices = getRegexpIndices(format, regexp);
      return formatWithSeparators(value, format, separator, regexp, indices);
    };

    expect(format("1", "hh:mm", ":")).toEqual("1");
    expect(format("12", "hh:mm", ":")).toEqual("12:");
    expect(format("121", "hh:mm", ":")).toEqual("12:1");
    expect(format("12:1", "hh:mm", ":")).toEqual("12:1");
    expect(format("1212", "hh:mm", ":")).toEqual("12:12");
    expect(format("12:12", "hh:mm", ":")).toEqual("12:12");
    expect(format("12121", "hh:mm", ":")).toEqual("12:12");
    expect(format("1", "hh:mm:ss", ":")).toEqual("1");
    expect(format("12", "hh:mm:ss", ":")).toEqual("12:");
    expect(format("121", "hh:mm:ss", ":")).toEqual("12:1");
    expect(format("12:1", "hh:mm:ss", ":")).toEqual("12:1");
    expect(format("1212", "hh:mm:ss", ":")).toEqual("12:12:");
    expect(format("12:12", "hh:mm:ss", ":")).toEqual("12:12:");
    expect(format("12121", "hh:mm:ss", ":")).toEqual("12:12:1");
    expect(format("15", "dd/mm/yyyy", "/")).toEqual("15/");
    expect(format("150", "dd/mm/yyyy", "/")).toEqual("15/0");
    expect(format("15/0", "dd/mm/yyyy", "/")).toEqual("15/0");
    expect(format("1505", "dd/mm/yyyy", "/")).toEqual("15/05/");
    expect(format("15/05", "dd/mm/yyyy", "/")).toEqual("15/05/");
    expect(format("1505200", "dd/mm/yyyy", "/")).toEqual("15/05/200");
    expect(format("15052000", "dd/mm/yyyy", "/")).toEqual("15/05/2000");
    expect(format("15/05/2000", "dd/mm/yyyy", "/")).toEqual("15/05/2000");
  });
});
